pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data, uint256 extraDeposit) public {
        vm.assume(target != address(0) && target != address(c));
        vm.assume(value <= 1e18);
        vm.assume(extraDeposit <= 1e18);

        // Fund the contract with some initial balance
        vm.deal(address(c), 2e18);

        // Record initial state
        uint256 initialOwnerBalance = address(this).balance;
        uint256 initialContractBalance = address(c).balance;
        uint256 initialDepositsCount = c.depositsCount();

        // Make a deposit first
        (bool depositSuccess, ) = address(c).call{value: extraDeposit}("");
        require(depositSuccess, "Deposit failed");

        // Now call sendMoney via the public entry
        if (value <= address(c).balance) {
            c.sendMoney(target, value, data);
        } else {
            // If value exceeds balance, expect revert
            vm.expectRevert();
            c.sendMoney(target, value, data);
            // If reverted, the invariant still holds trivially
            assertTrue(true);
            return;
        }

        // After sendMoney, the invariant: 
        // The contract balance decreased by exactly the value sent
        // and the owner's balance stays the same
        uint256 finalContractBalance = address(c).balance;
        uint256 finalOwnerBalance = address(this).balance;
        uint256 finalDepositsCount = c.depositsCount();

        // The deposit counts should have increased by 1 (from the extra deposit call) plus possibly 0 from sendMoney
        assertTrue(finalDepositsCount == initialDepositsCount + 1);

        // The contract balance should be: initial + extraDeposit - value
        assertTrue(finalContractBalance == initialContractBalance + extraDeposit - value);

        // The owner balance should not change from sendMoney call (only from deposit via fallback)
        // but since the deposit comes from this contract's fallback, it doesn't affect owner balance
        assertTrue(finalOwnerBalance == initialOwnerBalance);
    }
}

