pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 value, bytes memory data, uint256 preBalance) public {
        vm.assume(sender != address(0));
        vm.assume(value <= address(c).balance); // avoid revert due to insufficient balance
        // Record balance before operation
        uint256 balanceBefore = address(c).balance;
        // Drive the contract, ending with sendMoney
        if (sender != address(c)) {
            vm.prank(sender);
            // we need owner to call sendMoney, but sender may not be owner so we skip
        }
        // To ensure we can call sendMoney as owner, we set owner to this test contract
        // Since we cannot change owner, we call via prank with owner
        address owner = c.owner();
        vm.prank(owner);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", sender, value, data));
        // If the call reverts due to non-owner, skip this case
        if (!success) return;
        // General rule: balance should equal balanceBefore (since sendMoney does not change balance)
        assertTrue(address(c).balance == balanceBefore, "Balance changed after sendMoney");
    }
}

