import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 value, bytes memory data) public {
        vm.assume(caller != address(0));
        vm.assume(value <= address(c).balance);

        // Record state before sendMoney
        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = address(c.owner()).balance;
        uint256 depositsBefore = c.depositsCount();

        // Perform call with a different caller (simulate an EOA)
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", address(c), value, data));

        // Only consider successful calls
        if (success) {
            uint256 balanceAfter = address(c).balance;
            uint256 ownerBalanceAfter = address(c.owner()).balance;
            uint256 depositsAfter = c.depositsCount();

            // The invariant: contract balance change equals (owner balance change) + (value sent) 
            // but the bug sends to itself so owner balance change is 0 and contract balance stays same
            // The correct version: contract balance decreases by value, owner balance increases by value
            assertTrue(
                (int256(balanceAfter) - int256(balanceBefore)) == 
                (int256(ownerBalanceBefore) - int256(ownerBalanceAfter)) + int256(value),
                "Balance invariant violated"
            );
        }
    }
}

