pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Restrict to prevent overflow/underflow and avoid direct self-call interference
        _target = address(uint160(bound(uint160(_target), 1, type(uint160).max - 1)));
        vm.assume(_target != address(c) && _target != address(this) && _target != address(0));
        _value = bound(_value, 1, address(this).balance / 2);

        // Fund the contract
        vm.deal(address(c), 10 ether);
        // Record owner's balance
        address owner = c.owner();
        uint256 ownerBefore = owner.balance;

        // Call sendMoney, which may revert if the target has no payable fallback
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", _target, _value, _data));

        // Only evaluate when the call succeeded (i.e., the target accepted the value)
        vm.assume(success);

        // For the reference, the contract's balance decreases by _value only if the call succeeded
        // The buggy version always decreases the contract's balance
        // But we check owner's balance: reference does not change owner balance on any call,
        // while buggy version decreases it (since transfer uses msg.sender)
        uint256 ownerAfter = owner.balance;
        // In reference: owner balance unchanged because it's a call from contract, not transfer
        assertTrue(ownerAfter == ownerBefore, "Owner balance should not change in reference");
    }
}

